(() => {
  // DSM 应用外观层: 顶部悬浮栏(状态胶囊)、品牌区/欢迎区吉祥物。
  // 与主题无关, 官方/内置/自定义主题下均生效; 自定义吉祥物经
  // window.__dsmMascotURL(dataURL) 覆盖默认形象。
  if (window.__dsmAppChrome) return;
  window.__dsmAppChrome = true;

  const DEFAULT_MASCOT = "data:image/png;base64,";
  let mascotURL = (typeof window.__dsmMascotURL === "string" && window.__dsmMascotURL)
    ? window.__dsmMascotURL
    : DEFAULT_MASCOT;

  const postNative = (name, message) => {
    try { window.webkit?.messageHandlers?.[name]?.postMessage(message); } catch (_) {}
  };

  // ---------- 顶部悬浮栏 ----------
  const bar = document.createElement("div");
  bar.id = "dsmTopbar";
  // 左侧品牌区: 吉祥物常驻顶栏, 不依赖 dsh 侧边栏的显示状态
  const brand = document.createElement("div");
  brand.id = "dsmTopbarBrand";
  const topAv = document.createElement("span");
  topAv.id = "dsmTopAvatar";
  brand.appendChild(topAv);
  const status = document.createElement("button");
  status.type = "button";
  status.id = "dsmTopStatus";
  status.dataset.state = "starting";
  status.innerHTML = '<span class="dsm-top-dot"></span><span class="dsm-top-label">正在启动</span>';
  bar.appendChild(brand);
  bar.appendChild(status);
  document.body.appendChild(bar);

  const labels = { online: "已连接", starting: "正在启动", offline: "服务异常" };
  let topState = "starting";
  window.__dsmSetTopStatus = (st) => {
    topState = st;
    status.dataset.state = st;
    status.querySelector(".dsm-top-label").textContent = labels[st] || labels.offline;
    status.title = st === "online" ? "本地服务运行正常" : "点击尝试恢复本地服务";
  };
  status.addEventListener("click", () => {
    postNative("dsmService", topState === "online" ? "check" : "recover");
  });

  // ---------- 吉祥物替换 ----------
  // dsh 侧边栏在不同状态下会隐藏品牌按钮(或 ::before 伪元素不渲染),
  // 所以品牌区吉祥物一律用真实 DOM 元素, cute/官方模式都装饰;
  // 顶栏左侧吉祥物则永远可见, 双保险。
  const isCute = () => document.documentElement.dataset.dsmTheme === "cute";
  const isOfficial = () => document.documentElement.dataset.dsmTheme === "official";

  // cute/自定义主题(均源自 cute 模板)的品牌按钮自带 ::before 吉祥物,
  // 真实元素接管后关掉伪元素, 避免重影
  if (!document.getElementById("dsmBrandBeforeKill")) {
    const kill = document.createElement("style");
    kill.id = "dsmBrandBeforeKill";
    kill.textContent = '[data-slot="sidebar"] button[class*="_brand"]::before{content:none !important}';
    document.head.appendChild(kill);
  }

  const applyMascot = (url) => {
    mascotURL = url || DEFAULT_MASCOT;
    topAv.style.backgroundImage = 'url("' + mascotURL + '")';
    document.querySelectorAll(".dsm-avatar").forEach((el) => {
      el.classList.toggle("dsm-has-mascot", Boolean(url));
      el.style.backgroundImage = 'url("' + mascotURL + '")';
    });
  };

  const decorateBrand = (button) => {
    if (button.dataset.dsmBrandDone) return;
    button.dataset.dsmBrandDone = "1";
    const identity = button.querySelector('[class*="_brandIdentity"]');
    const mark = button.querySelector('[class*="_brandMark"]');
    const name = button.querySelector('[class*="_brandName"]');
    if (mark) mark.style.display = "none";
    if (name) name.style.display = "none";
    const av = document.createElement("span");
    av.className = "dsm-avatar dsm-brand-avatar" + (isOfficial() ? "" : " dsm-brand-avatar-cute");
    (identity || (mark && mark.parentElement) || button).insertBefore(av, identity ? identity.firstChild : (mark || button.firstChild));
    applyMascot(mascotURL);
  };

  const decorateHero = (headline) => {
    if (headline.dataset.dsmHeroDone) return;
    const fish = headline.querySelector('svg[class*="_fish"], svg');
    if (!fish) return;
    headline.dataset.dsmHeroDone = "1";
    fish.style.display = "none";
    const hitbox = headline.querySelector('[class*="_fishHitbox"]') || headline;
    const av = document.createElement("span");
    av.className = "dsm-avatar dsm-hero-avatar";
    hitbox.insertBefore(av, hitbox.firstChild);
    applyMascot(mascotURL);
  };

  const scan = (root) => {
    root.querySelectorAll('button[class*="_brand"]').forEach(decorateBrand);
    if (!isCute()) root.querySelectorAll('[class*="_headline"]').forEach(decorateHero);
  };
  scan(document);

  let scanTimer = 0;
  const scheduleScan = () => {
    if (scanTimer) return;
    scanTimer = window.setTimeout(() => { scanTimer = 0; scan(document); }, 260);
  };
  const mo = new MutationObserver((records) => {
    let hit = false;
    for (const record of records) {
      for (const node of record.addedNodes) {
        if (node.nodeType !== Node.ELEMENT_NODE) continue;
        if (node.matches?.('button[class*="_brand"], [class*="_headline"]') ||
            node.querySelector?.('button[class*="_brand"], [class*="_headline"]')) { hit = true; break; }
      }
      if (hit) break;
    }
    if (hit) scheduleScan();
  });
  mo.observe(document.documentElement, { childList: true, subtree: true });

  // 主题切换时重建: 品牌吉祥物两种模式都由本层接管
  window.__dsmChromeRefresh = () => {
    document.querySelectorAll(".dsm-avatar").forEach((el) => el.remove());
    document.querySelectorAll("[data-dsm-brand-done]").forEach((el) => delete el.dataset.dsmBrandDone);
    document.querySelectorAll("[data-dsm-hero-done]").forEach((el) => delete el.dataset.dsmHeroDone);
    scan(document);
    applyMascot(mascotURL);
  };
  applyMascot(mascotURL);

  // 包装主题应用函数, 支持第三参数 mascot(dataURL)
  const origApply = window.__dsmApplyTheme;
  if (typeof origApply === "function") {
    window.__dsmApplyTheme = (id, css, mascot) => {
      if (mascot !== undefined) window.__dsmMascotURL = mascot || "";
      const r = origApply(id, css);
      window.__dsmChromeRefresh();
      return r;
    };
  }
  window.__dsmApplyMascot = (url) => {
    window.__dsmMascotURL = url || "";
    applyMascot(url);
  };
})();
